-- Baseline: captures the schema as generated by Hibernate ddl-auto=update up to this point.
-- On a database that already has these tables (e.g. the existing Neon instance), Flyway is
-- configured with baseline-on-migrate so this file is recorded as applied without re-running.
-- On a fresh database, running this creates the schema from scratch.

CREATE TABLE users (
    id            VARCHAR(255) NOT NULL PRIMARY KEY,
    name          VARCHAR(100) NOT NULL,
    email         VARCHAR(150) NOT NULL,
    password_hash VARCHAR(255) NOT NULL,
    created_at    TIMESTAMP WITH TIME ZONE NOT NULL,
    CONSTRAINT uk_users_email UNIQUE (email)
);

CREATE TABLE groups (
    id         VARCHAR(255) NOT NULL PRIMARY KEY,
    name       VARCHAR(100) NOT NULL,
    created_by VARCHAR(255) NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL,
    CONSTRAINT fk_groups_created_by FOREIGN KEY (created_by) REFERENCES users (id)
);

CREATE TABLE group_members (
    id        VARCHAR(255) NOT NULL PRIMARY KEY,
    group_id  VARCHAR(255) NOT NULL,
    user_id   VARCHAR(255) NOT NULL,
    joined_at TIMESTAMP WITH TIME ZONE NOT NULL,
    CONSTRAINT fk_group_members_group FOREIGN KEY (group_id) REFERENCES groups (id),
    CONSTRAINT fk_group_members_user FOREIGN KEY (user_id) REFERENCES users (id),
    CONSTRAINT uk_group_members_group_user UNIQUE (group_id, user_id)
);
CREATE INDEX idx_group_members_user ON group_members (user_id);

CREATE TABLE expenses (
    id          VARCHAR(255) NOT NULL PRIMARY KEY,
    group_id    VARCHAR(255) NOT NULL,
    paid_by     VARCHAR(255) NOT NULL,
    description VARCHAR(255) NOT NULL,
    amount      NUMERIC(12, 2) NOT NULL,
    split_type  VARCHAR(20) NOT NULL,
    category    VARCHAR(20) NOT NULL,
    created_at  TIMESTAMP WITH TIME ZONE NOT NULL,
    CONSTRAINT fk_expenses_group FOREIGN KEY (group_id) REFERENCES groups (id),
    CONSTRAINT fk_expenses_paid_by FOREIGN KEY (paid_by) REFERENCES users (id)
);
CREATE INDEX idx_expenses_group ON expenses (group_id);
CREATE INDEX idx_expenses_paid_by ON expenses (paid_by);

CREATE TABLE expense_shares (
    id            VARCHAR(255) NOT NULL PRIMARY KEY,
    expense_id    VARCHAR(255) NOT NULL,
    user_id       VARCHAR(255) NOT NULL,
    share_amount  NUMERIC(12, 2) NOT NULL,
    settled       BOOLEAN NOT NULL,
    CONSTRAINT fk_expense_shares_expense FOREIGN KEY (expense_id) REFERENCES expenses (id),
    CONSTRAINT fk_expense_shares_user FOREIGN KEY (user_id) REFERENCES users (id)
);
CREATE INDEX idx_expense_shares_expense ON expense_shares (expense_id);
CREATE INDEX idx_expense_shares_user ON expense_shares (user_id);

CREATE TABLE settlements (
    id          VARCHAR(255) NOT NULL PRIMARY KEY,
    group_id    VARCHAR(255) NOT NULL,
    from_user   VARCHAR(255) NOT NULL,
    to_user     VARCHAR(255) NOT NULL,
    amount      NUMERIC(12, 2) NOT NULL,
    settled_at  TIMESTAMP WITH TIME ZONE NOT NULL,
    CONSTRAINT fk_settlements_group FOREIGN KEY (group_id) REFERENCES groups (id),
    CONSTRAINT fk_settlements_from_user FOREIGN KEY (from_user) REFERENCES users (id),
    CONSTRAINT fk_settlements_to_user FOREIGN KEY (to_user) REFERENCES users (id)
);
CREATE INDEX idx_settlements_group ON settlements (group_id);

CREATE TABLE notifications (
    id           VARCHAR(255) NOT NULL PRIMARY KEY,
    recipient_id VARCHAR(255) NOT NULL,
    type         VARCHAR(30) NOT NULL,
    message      VARCHAR(255) NOT NULL,
    group_id     VARCHAR(255),
    read         BOOLEAN NOT NULL,
    created_at   TIMESTAMP WITH TIME ZONE NOT NULL,
    CONSTRAINT fk_notifications_recipient FOREIGN KEY (recipient_id) REFERENCES users (id)
);
CREATE INDEX idx_notifications_recipient ON notifications (recipient_id);

CREATE TABLE recurring_expense_templates (
    id          VARCHAR(255) NOT NULL PRIMARY KEY,
    group_id    VARCHAR(255) NOT NULL,
    created_by  VARCHAR(255) NOT NULL,
    paid_by     VARCHAR(255) NOT NULL,
    description VARCHAR(255) NOT NULL,
    amount      NUMERIC(12, 2) NOT NULL,
    category    VARCHAR(20) NOT NULL,
    split_type  VARCHAR(20) NOT NULL,
    frequency   VARCHAR(20) NOT NULL,
    next_run_at TIMESTAMP WITH TIME ZONE NOT NULL,
    active      BOOLEAN NOT NULL,
    created_at  TIMESTAMP WITH TIME ZONE NOT NULL,
    CONSTRAINT fk_ret_group FOREIGN KEY (group_id) REFERENCES groups (id),
    CONSTRAINT fk_ret_created_by FOREIGN KEY (created_by) REFERENCES users (id),
    CONSTRAINT fk_ret_paid_by FOREIGN KEY (paid_by) REFERENCES users (id)
);
CREATE INDEX idx_ret_group ON recurring_expense_templates (group_id);

CREATE TABLE recurring_expense_participants (
    template_id VARCHAR(255) NOT NULL,
    user_id     VARCHAR(255) NOT NULL,
    CONSTRAINT fk_rep_template FOREIGN KEY (template_id) REFERENCES recurring_expense_templates (id)
);
CREATE INDEX idx_rep_template ON recurring_expense_participants (template_id);

CREATE TABLE refresh_tokens (
    id         VARCHAR(255) NOT NULL PRIMARY KEY,
    user_id    VARCHAR(255) NOT NULL,
    token_hash VARCHAR(255) NOT NULL,
    expires_at TIMESTAMP WITH TIME ZONE NOT NULL,
    revoked    BOOLEAN NOT NULL,
    created_at TIMESTAMP WITH TIME ZONE NOT NULL,
    CONSTRAINT fk_refresh_tokens_user FOREIGN KEY (user_id) REFERENCES users (id),
    CONSTRAINT uk_refresh_tokens_token_hash UNIQUE (token_hash)
);
CREATE INDEX idx_refresh_tokens_user ON refresh_tokens (user_id);
